-- Ejecutar como administrador; configurar contraseña de planner_app por separado.
CREATE SCHEMA IF NOT EXISTS planner;
REVOKE ALL ON SCHEMA planner FROM PUBLIC;
SET search_path TO planner;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password TEXT,google_sub TEXT UNIQUE,verified INTEGER NOT NULL DEFAULT 0,preferences TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',course_id TEXT NOT NULL,due_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','working','done')),visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')),effort INTEGER NOT NULL DEFAULT 60,importance INTEGER NOT NULL DEFAULT 2,reminder INTEGER NOT NULL DEFAULT 1440,created_at TEXT NOT NULL,completed_at TEXT);
CREATE INDEX IF NOT EXISTS tasks_owner ON tasks(user_id);
CREATE INDEX IF NOT EXISTS tasks_public_course ON tasks(visibility,course_id);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,data BYTEA NOT NULL);
CREATE TABLE IF NOT EXISTS enrollments(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,course_id TEXT NOT NULL,PRIMARY KEY(user_id,course_id));
CREATE TABLE IF NOT EXISTS grades(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,course_id TEXT NOT NULL,components TEXT NOT NULL,PRIMARY KEY(user_id,course_id));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,reminder_key TEXT NOT NULL UNIQUE,title TEXT NOT NULL,created_at TEXT NOT NULL,seen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS oauth_states(state TEXT PRIMARY KEY,browser_token TEXT NOT NULL,verifier TEXT NOT NULL,nonce TEXT NOT NULL,mode TEXT NOT NULL,user_id TEXT,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS calendar_connections(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,tokens TEXT NOT NULL,calendar_id TEXT);
CREATE TABLE IF NOT EXISTS calendar_events(task_id TEXT PRIMARY KEY REFERENCES tasks(id) ON DELETE CASCADE,event_id TEXT NOT NULL);
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE grades ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE oauth_states ENABLE ROW LEVEL SECURITY;
ALTER TABLE calendar_connections ENABLE ROW LEVEL SECURITY;
ALTER TABLE calendar_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA planner FROM PUBLIC;

DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='planner_app') THEN CREATE ROLE planner_app NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION; END IF; END $$;
GRANT USAGE ON SCHEMA planner TO planner_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA planner TO planner_app;
DO $$ DECLARE t text; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='planner' LOOP IF NOT EXISTS (SELECT FROM pg_policies WHERE schemaname='planner' AND tablename=t AND policyname='server_access') THEN EXECUTE format('CREATE POLICY server_access ON planner.%I TO planner_app USING (true) WITH CHECK (true)',t); END IF; END LOOP; END $$;
